def max_product(t):
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        max_product = 0
        for i in range(n):
            for j in range(n):
                if i != j:
                    product = 1
                    for k in range(n):
                        if k != i and k != j:
                            product *= a[k]
                    if product > max_product:
                        max_product = product
        print(max_product)

# Example usage
max_product(4)

def min_travel_time(N, A, B, C, D):
    # 初始化dp数组，dp[i][j]表示从城市i到城市j的最小旅行时间
    dp = [[float('inf')] * N for _ in range(N)]
    # 初始化起点到自己的时间
    dp[0][0] = 0
    # 遍历所有可能的路径
    for i in range(N):
        for j in range(N):
            if i == j:
                continue
            # 从公司车到公司车
            if i == 0:
                dp[i][j] = min(dp[i][j], dp[i][0] + D[i][j] * A)
            # 从公司车到火车
            elif i == 1:
                dp[i][j] = min(dp[i][j], dp[i][0] + D[i][j] * A + D[i][j] * B + C)
            # 从火车到公司车
            elif i == 2:
                dp[i][j] = min(dp[i][j], dp[i][0] + D[i][j] * A + D[i][j] * B + C)
            # 从火车到火车
            else:
                dp[i][j] = min(dp[i][j], dp[i][0] + D[i][j] * A + D[i][j] * B + C)
    # 返回终点到自己的最小旅行时间
    return dp[N-1][N-1]

def total_score(N, X, S):
    total = 0
    for i in range(N):
        if S[i] <= X:
            total += S[i]
    print(total)
N, X = map(int, input().split())
S = list(map(int, input().split()))
total_score(N, X, S)

